from common_e14 import *
import pandas as pd,numpy as np
from deliver_e14 import mdtable
def main():
 study=pd.read_csv(R/'SEED_CONTEXT_METRICS.csv');mean=study.groupby(['model','condition']).mean(numeric_only=True);rowsout=[]
 for condition in ['FULL','X50','X43']:
  a=mean.loc['N1',condition];b=mean.loc['N2',condition];rowsout.append(dict(condition=condition,N1_L2=a.equal_plate_L2,N2_L2=b.equal_plate_L2,N2_L2_change_percent=100*(b.equal_plate_L2/a.equal_plate_L2-1),N1_High95_IoU=a.equal_plate_high95_IoU,N2_High95_IoU=b.equal_plate_high95_IoU,IoU_absolute_change=b.equal_plate_high95_IoU-a.equal_plate_high95_IoU))
 table(R/'16_plate_metrics/EXECUTIVE_N1_N2_MEAN_COMPARISON.csv',rowsout);pairs=pd.read_csv(R/'16_plate_metrics/PAIRED_PLATE_COMPARISON.csv');heter=[]
 for condition in ['FULL','X50','X43']:
  p=pairs[pairs.condition==condition];heter.append(dict(condition=condition,plate_seed_pairs=len(p),N2_lower_L2_pairs=int((p.N2_minus_N1_L2<0).sum()),N2_higher_IoU_pairs=int((p.N2_minus_N1_IoU>0).sum()),note='10 correlated plate-seed pairs represent five documentary plates; not 10 independent cohorts'))
 table(R/'16_plate_metrics/PLATE_HETEROGENEITY_COUNTS.csv',heter);control=[]
 for seed in [20261021,20261022]:
  a=study[(study.model=='N1')&(study.seed==seed)&(study.condition=='FULL')].iloc[0];b=study[(study.model=='N1')&(study.seed==seed)&(study.condition=='D0')].iloc[0];control.append(dict(seed=seed,D0_minus_FULL_L2=b.equal_plate_L2-a.equal_plate_L2,D0_minus_FULL_IoU=b.equal_plate_high95_IoU-a.equal_plate_high95_IoU))
 text='## Scientific synthesis\n\nThe unchanged N1 predictor is sensitive to the specified cropped observation protocol. A single fixed context-diversified N2 training recipe reduces restricted-view field error but sacrifices full-view accuracy and does not improve High95 localization consistently across seeds. This is an **accuracy/robustness trade-off**, not an unqualified replacement model.\n\nThe table averages separately scored equal-plate metrics over both seeds; it is not an ensemble-field score.\n\n'+mdtable(pd.DataFrame(rowsout))+'\n\nThe same architecture, initialization seed slots and source-original query draws were retained. Every actual training query and context membership was independently replayed. No extra epochs, widths, variants or favorable seeds were added after the outcome.\n\nThe nonuniform density control changes N1 much less than the full cropping intervention:\n\n'+mdtable(pd.DataFrame(control))+'\n\nD0 keeps the full visible feature/neighbor geometry while redistributing pooled context samples. It is a partial control, so these results do not isolate any one feature channel or identify a physical mechanism. Window-global normalization, missing global shape information and tile stitching remain plausible representation mechanisms requiring separately authorized tests.\n\nPlate heterogeneity remains important:\n\n'+mdtable(pd.DataFrame(heter))+'\n\nFULL accuracy and hotspot localization must therefore accompany any claim of context stability. Continuous predicted/reference variance ratios and peak/Q95 biases rule out interpreting a small field shift alone as a successful stress predictor. Keep N1 and N2 as frozen research comparisons; this phase selects no production seed, preferred observation width or physical grinding strategy. A fresh confirmatory cohort requires unused documented parent plates/batches, not further coupons from the five already exposed plates.\n\n'
 for name in ['R8E14_MASTER_REPORT.md','FINAL_R8E14_DECISION.md','MODEL_COMPARISON_SYNTHESIS.md']:
  p=R/name
  if p.exists():content=p.read_text(encoding='utf8');i=content.find('\n\n');p.write_text(content[:i+2]+text+content[i+2:],encoding='utf8')
  else:p.write_text('# R8-E14 model comparison synthesis\n\n'+text,encoding='utf8')
 qualification=pd.read_csv(R/'QUALIFIED13_SOURCE_REGISTRY.csv');precision=qualification[['source_id','T2_L2','T2_worst_regional_L2','T2_high95_IoU','mapping_coverage']];precision.to_csv(R/'19_reports/NUMERICAL_TARGET_PRECISION.csv',index=False);p=R/'19_reports/NUMERICAL_TARGET_PRECISION_CONTEXT.md';p.write_text('# Historical numerical precision context\n\n'+mdtable(precision)+'\nThese conditional M1/M2 differences are descriptive mesh-level consistency diagnostics. They are neither physical measurement uncertainty nor rigorous FE error bounds or attainable-ML-error limits. No discrepancy is subtracted from the prediction error. No new FE simulation was performed.\n',encoding='utf8');print('SCIENTIFIC_SYNTHESIS_COMPLETE',flush=True)
if __name__=='__main__':main()
